# 1. Append to swift-data.json
with open('swift-data.json') as f:
    existing = json.load(f)

# Remove old mt564 if any
existing = [x for x in existing if x.get('msg') != 'mt564']
existing.extend(MT564)

with open('swift-data.json', 'w') as f:
    json.dump(existing, f, indent=2, ensure_ascii=False)
print(f"swift-data.json: {len(existing)} total items ({len(MT564)} mt564 added)")

# 2. Inject into FALLBACK_DATA in HTML
js_lines = [f"      {json.dumps(item, ensure_ascii=False)}," for item in MT564]
mt564_js = "\n      // ===== MT 564 =====\n" + "\n".join(js_lines)

with open('swift-reporting-tabular.html') as f:
    html = f.read()

# Find end of FALLBACK_DATA and insert before closing ]
pattern = r'(\n    \];)'
match = re.search(pattern, html)
if match:
    new_html = html[:match.start()] + mt564_js + html[match.start():]
    with open('swift-reporting-tabular.html', 'w') as f:
        f.write(new_html)
    print("Injected MT564 into FALLBACK_DATA in swift-reporting-tabular.html")
else:
    print("ERROR: Could not find FALLBACK_DATA closing bracket")
